style.css:
/* This applies a GIF background to the entire Roblox page */
body {
  background-image: url('https://makeagif.com/gif/wallpaper-engine-miku-hatsune-vocaloid-official-wallpaper-video-DkzbI9')!important; /* URL of your GIF */
  background-size: cover; /* Make the GIF cover the entire page */
  background-position: center; /* Center the GIF */
  background-repeat: no-repeat; /* Prevent the GIF from repeating */
  margin: 0; /* Remove default margin */
  height: 100vh; /* Ensure the body fills the entire viewport */
  overflow: hidden; /* Prevent any scrolling if you only want the GIF as background */
}

/* Optional: Add this to ensure content is readable on top of the GIF */
* {
  color: white; /* Make text color white to stand out against the background */
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.6); /* Add a shadow to make text more readable */
}
